import { test, expect } from '@playwright/test';

test.describe('WebSocket Real-time UI Updates', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should update UI in real-time when WebSocket receives new data', async ({ page }) => {
    // Setup: Open WebSocket connection
    const ws = page.waitForResponse(response => response.url().includes('/ws/data'));
    await page.route('**/ws/data', route => {
      route.continue();
    });

    // Verify initial state
    const dataTable = page.getByRole('table', { name: /data table/i });
    await expect(dataTable).toBeVisible();

    // Verify initial data
    const tableRows = page.locator('[data-testid="data-row"]');
    await expect(tableRows).toHaveCount(3);

    // Send WebSocket message to trigger update
    const updateButton = page.getByRole('button', { name: /update data/i });
    await updateButton.click();

    // Wait for WebSocket response
    await expect(ws).toBefulfilled();

    // Verify UI updates
    const updatedRows = page.locator('[data-testid="data-row"]');
    await expect(updatedRows).toHaveCount(5);

    // Verify new data is displayed
    const newDataRow = page.getByText(/New Data/i);
    await expect(newDataRow).toBeVisible();

    // Verify UI is responsive
    const loadingIndicator = page.getByRole('status');
    await expect(loadingIndicator).toBeVisible();

    // Verify error state is not set
    const errorMessage = page.getByText(/error/i);
    await expect(errorMessage).not.toBeVisible();
  });

  test('should handle WebSocket disconnection and reconnect', async ({ page }) => {
    // Setup: Open WebSocket connection
    const ws = page.waitForResponse(response => response.url().includes('/ws/data'));
    await page.route('**/ws/data', route => {
      route.continue();
    });

    // Verify initial state
    const dataTable = page.getByRole('table', { name: /data table/i });
    await expect(dataTable).toBeVisible();

    // Verify initial data
    const tableRows = page.locator('[data-testid="data-row"]');
    await expect(tableRows).toHaveCount(3);

    // Simulate WebSocket disconnection
    await page.route('**/ws/data', route => {
      route.abort();
    });

    // Wait for disconnection
    await page.waitForTimeout(100);

    // Verify UI remains responsive
    const loadingIndicator = page.getByRole('status');
    await expect(loadingIndicator).toBeVisible();

    // Verify error state is not set
    const errorMessage = page.getByText(/error/i);
    await expect(errorMessage).not.toBeVisible();

    // Verify data is still displayed
    const dataRow = page.getByText(/Data 1/i);
    await expect(dataRow).toBeVisible();

    // Reconnect WebSocket
    await page.route('**/ws/data', route => {
      route.continue();
    });

    // Verify UI updates after reconnection
    const updatedRows = page.locator('[data-testid="data-row"]');
    await expect(updatedRows).toHaveCount(3);

    // Verify new data is displayed
    const newDataRow = page.getByText(/New Data/i);
    await expect(newDataRow).toBeVisible();

    // Verify error state is cleared
    const errorMessage = page.getByText(/error/i);
    await expect(errorMessage).not.toBeVisible();
  });
});
